import{_ as s,o as e,c as i,a4 as a}from"./chunks/framework.BMj-uaUw.js";const k=JSON.parse('{"title":"2.4 构建工具与 Vite","description":"","frontmatter":{},"headers":[{"level":2,"title":"浏览器看不懂我们写的文件","slug":"浏览器看不懂我们写的文件","link":"#浏览器看不懂我们写的文件","children":[]},{"level":2,"title":"构建工具做的三件事","slug":"构建工具做的三件事","link":"#构建工具做的三件事","children":[]},{"level":2,"title":"Vite 最特别的地方：开发态和生产态走两条路","slug":"vite-最特别的地方-开发态和生产态走两条路","link":"#vite-最特别的地方-开发态和生产态走两条路","children":[]},{"level":2,"title":"为什么冷启动快：依赖预构建","slug":"为什么冷启动快-依赖预构建","link":"#为什么冷启动快-依赖预构建","children":[{"level":3,"title":"依赖预构建解决三个问题","slug":"依赖预构建解决三个问题","link":"#依赖预构建解决三个问题","children":[]}]},{"level":2,"title":"HMR：改代码之后页面为什么能局部刷新","slug":"hmr-改代码之后页面为什么能局部刷新","link":"#hmr-改代码之后页面为什么能局部刷新","children":[{"level":3,"title":"热更新失效的常见现象","slug":"热更新失效的常见现象","link":"#热更新失效的常见现象","children":[]}]},{"level":2,"title":"生产态为什么必须用 Rollup 打包","slug":"生产态为什么必须用-rollup-打包","link":"#生产态为什么必须用-rollup-打包","children":[]},{"level":2,"title":"和 Webpack 比，差在哪","slug":"和-webpack-比-差在哪","link":"#和-webpack-比-差在哪","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"常见坑","slug":"常见坑","link":"#常见坑","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"unit02/04-vite.md","filePath":"unit02/04-vite.md","lastUpdated":1789307994000}'),d={name:"unit02/04-vite.md"};function n(l,t,p,o,r,c){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="_2-4-构建工具与-vite" tabindex="-1">2.4 构建工具与 Vite <a class="header-anchor" href="#_2-4-构建工具与-vite" aria-label="Permalink to &quot;2.4 构建工具与 Vite&quot;">​</a></h1><h2 id="浏览器看不懂我们写的文件" tabindex="-1">浏览器看不懂我们写的文件 <a class="header-anchor" href="#浏览器看不懂我们写的文件" aria-label="Permalink to &quot;浏览器看不懂我们写的文件&quot;">​</a></h2><p>在 <code>src/App.vue</code> 里写下第一个组件之后，你可能会想：<strong>能不能不用 Vite，直接双击 <code>index.html</code> 打开？</strong></p><p>试试看。把 <code>index.html</code> 里的 <code>&lt;script type=&quot;module&quot; src=&quot;/src/main.js&quot;&gt;&lt;/script&gt;</code> 保持不变，直接用浏览器打开这个文件，控制台会给你一串报错：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Failed to load module script: Expected a JavaScript module script but the server</span></span>
<span class="line"><span>responded with a MIME type of &quot;text/html&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET http://127.0.0.1:5500/src/App.vue net::ERR_ABORTED</span></span>
<span class="line"><span>Uncaught TypeError: Failed to resolve module specifier &quot;vue&quot;.</span></span></code></pre></div><p>三个报错对应三个问题：</p><table tabindex="0"><thead><tr><th>报错</th><th>原因</th></tr></thead><tbody><tr><td><code>MIME type of &quot;text/html&quot;</code></td><td>用 <code>file://</code> 打开时，<code>/src/main.js</code> 被当成路径找文件，找不到就返回了 HTML</td></tr><tr><td><code>Failed to resolve module specifier &quot;vue&quot;</code></td><td>浏览器不认识裸模块名，<code>import &#39;vue&#39;</code> 不知道该去哪个文件找</td></tr><tr><td><code>App.vue</code> 加载失败</td><td><strong>浏览器根本不认识 <code>.vue</code> 文件</strong></td></tr></tbody></table><p>第三行最关键。<code>.vue</code> 文件是一种自定义格式，里面有 <code>&lt;template&gt;</code>、<code>&lt;script&gt;</code>、 <code>&lt;style&gt;</code> 三块，浏览器没有对应处理器。同样的问题还有：</p><table tabindex="0"><thead><tr><th>我们写的</th><th>浏览器认不认</th></tr></thead><tbody><tr><td><code>.vue</code> 单文件组件</td><td>✗ 不认识</td></tr><tr><td><code>.scss</code> / <code>.sass</code> 样式文件</td><td>✗ 不认识</td></tr><tr><td><code>.ts</code> 类型标注</td><td>✗ 不认识</td></tr><tr><td><code>import &#39;vue&#39;</code> 裸模块名</td><td>✗ 不知道去哪找</td></tr><tr><td><code>@/components/Foo.vue</code> 别名</td><td>✗ 不知道 <code>@</code> 是什么</td></tr><tr><td>可选链之外更新的语法</td><td>部分不支持</td></tr></tbody></table><p><strong>构建工具的存在理由就是这一件事：把我们写的、浏览器看不懂的代码，翻译成浏览器能看懂的代码。</strong></p><h2 id="构建工具做的三件事" tabindex="-1">构建工具做的三件事 <a class="header-anchor" href="#构建工具做的三件事" aria-label="Permalink to &quot;构建工具做的三件事&quot;">​</a></h2><p>不管叫什么名字（Vite、Webpack、Rspack、Rollup），构建工具都在做三件事：</p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>例子</th></tr></thead><tbody><tr><td>转换</td><td>把不可识别的格式换成标准 JS / CSS</td><td><code>.vue</code> → <code>.js</code>、<code>.scss</code> → <code>.css</code></td></tr><tr><td>解析</td><td>把裸模块名和别名换成真实路径</td><td><code>import &#39;vue&#39;</code> → <code>./node_modules/.pnpm/vue@3.5.42/.../vue.runtime.esm-bundler.js</code></td></tr><tr><td>打包</td><td>把成百上千个模块合并、压缩、拆分</td><td>产物放进 <code>dist/</code></td></tr></tbody></table><p>第一件事回答“浏览器不认识什么”，第二件事回答“文件在哪”，第三件事回答 “交付给用户的是哪些文件”。</p><h2 id="vite-最特别的地方-开发态和生产态走两条路" tabindex="-1">Vite 最特别的地方：开发态和生产态走两条路 <a class="header-anchor" href="#vite-最特别的地方-开发态和生产态走两条路" aria-label="Permalink to &quot;Vite 最特别的地方：开发态和生产态走两条路&quot;">​</a></h2><p>其他构建工具在开发时和生产时做的事情差不多，都是“把所有代码打包成几个文件”。 Vite 不一样，它把这两件事<strong>分开做</strong>：</p><table tabindex="0"><thead><tr><th>对比项</th><th>开发态（<code>pnpm dev</code>）</th><th>生产态（<code>pnpm build</code>）</th></tr></thead><tbody><tr><td>底层</td><td>浏览器原生 ES Module + esbuild 转换</td><td>Rollup 打包</td></tr><tr><td>是否打包</td><td><strong>不打包</strong>，按需编译</td><td>打包成少量文件</td></tr><tr><td>产物在哪</td><td>不写磁盘，在内存里</td><td><code>dist/</code> 目录</td></tr><tr><td>启动速度</td><td>秒级，与项目规模关系不大</td><td>几秒到几十秒，与项目规模相关</td></tr><tr><td>目标</td><td>改代码后立刻能看到</td><td>给真实用户下载，体积和性能优先</td></tr></tbody></table><p>为什么开发态可以不打包？因为<strong>现代浏览器原生支持 ES Module</strong>。浏览器自己能处理 <code>import &#39;/src/App.vue&#39;</code> 这种请求 —— 只要服务器返回的是一段合法的 JS。</p><p>于是 Vite 的开发服务器变成了一个“<strong>按需翻译</strong>”的服务：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器请求 /src/main.js</span></span>
<span class="line"><span>  → Vite 读到文件，把里面的裸模块名和别名改写成浏览器能请求的路径</span></span>
<span class="line"><span>  → 返回改写后的 JS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>浏览器接着请求 /src/App.vue</span></span>
<span class="line"><span>  → Vite 用 @vitejs/plugin-vue 把 .vue 编译成普通 JS</span></span>
<span class="line"><span>  → 返回编译结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>浏览器再请求 /src/style.css（由 .scss 编译而来）</span></span>
<span class="line"><span>  → Vite 编译 sass，返回 CSS</span></span></code></pre></div><p>关键点：<strong>只有浏览器请求到的文件才会被编译</strong>。你有 200 个页面组件， 但首页只用到 5 个，那启动时只编译这 5 个。这就是为什么一个几百个文件的项目 也能秒级启动。</p><h2 id="为什么冷启动快-依赖预构建" tabindex="-1">为什么冷启动快：依赖预构建 <a class="header-anchor" href="#为什么冷启动快-依赖预构建" aria-label="Permalink to &quot;为什么冷启动快：依赖预构建&quot;">​</a></h2><p>开发态不打包，那 <code>node_modules</code> 里那几百个依赖怎么办？总不能每个都让浏览器单独请求一次 —— <code>element-plus</code> 一个库就有上千个模块，浏览器要发上千个请求，页面会卡半天。</p><p>Vite 在第一次启动时会先做一次<strong>依赖预构建</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VITE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v8.3.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ready</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 412</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ms</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ➜</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Local:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   http://localhost:5173/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ➜</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Network:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ➜</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  press</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span></code></pre></div><p>如果你删掉 <code>node_modules/.vite</code> 再启动，会先看到这样一段，然后才是 ready：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node_modules/.vite/deps/</span></span>
<span class="line"><span>├── _metadata.json</span></span>
<span class="line"><span>├── vue.js</span></span>
<span class="line"><span>├── element-plus.js</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><h3 id="依赖预构建解决三个问题" tabindex="-1">依赖预构建解决三个问题 <a class="header-anchor" href="#依赖预构建解决三个问题" aria-label="Permalink to &quot;依赖预构建解决三个问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>具体表现</th><th>预构建怎么解决</th></tr></thead><tbody><tr><td>模块数量太多</td><td><code>element-plus</code> 有上千个内部模块，浏览器要发上千个请求</td><td>用 esbuild 把上百个模块合成一个文件，请求数降到个位数</td></tr><tr><td>格式不统一</td><td>很多 npm 包还是 CommonJS 格式，浏览器只认 ES Module</td><td>统一转成 ES Module</td></tr><tr><td>每次启动都重复处理</td><td>依赖很少变，每次都重新处理是浪费</td><td>结果缓存在 <code>node_modules/.vite/deps</code>，只有依赖变了才重新构建</td></tr></tbody></table><p>对比一下“处理”的对象就能明白 Vite 的设计取向：</p><table tabindex="0"><thead><tr><th>对象</th><th>处理方式</th><th>理由</th></tr></thead><tbody><tr><td>依赖（<code>node_modules</code>）</td><td>启动时一次性预构建，然后缓存</td><td>内容不常变，数量多，适合批量处理</td></tr><tr><td>你的源码（<code>src/</code>）</td><td>每次请求时按需编译，不缓存</td><td>内容常变，数量少，逐个处理最省时间</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>node_modules/.vite</code> 什么时候要删</p><p>这个缓存目录偶尔会出问题。典型现象是：改了依赖版本，但开发服务器还是在用旧版本； 或者报错信息里出现的代码和你的源码对不上。</p><p>处理方式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules/.vite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><strong>注意是 <code>node_modules/.vite</code>，不是 <code>node_modules</code>。</strong> 前者是缓存，删了不心疼； 后者要重装依赖，能不动就不动。</p></div><h2 id="hmr-改代码之后页面为什么能局部刷新" tabindex="-1">HMR：改代码之后页面为什么能局部刷新 <a class="header-anchor" href="#hmr-改代码之后页面为什么能局部刷新" aria-label="Permalink to &quot;HMR：改代码之后页面为什么能局部刷新&quot;">​</a></h2><p>HMR 是 Hot Module Replacement（模块热替换）的缩写。它解决的问题是： <strong>改一行代码，不想丢掉当前页面状态。</strong></p><p>想象一下你在调试活动报名审核弹窗：填了一半的表单、展开的下拉框、滚到了第三屏。 如果没有 HMR，你一保存代码页面就整页刷新，所有状态清零，又得从头点到那个位置。</p><p>Vite 的 HMR 大致是这样工作的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 你在编辑器里保存 src/views/ActivityListView.vue</span></span>
<span class="line"><span>2. Vite 开发服务器通过 WebSocket 告诉浏览器：“这个文件变了”</span></span>
<span class="line"><span>3. 浏览器里的 HMR 运行时收到消息，问：“这个模块能热替换吗？”</span></span>
<span class="line"><span>4. 能 —— 只重新加载这个模块，页面其他部分和状态都不动</span></span>
<span class="line"><span>   不能 —— 往上找到最近一个能热替换的模块</span></span>
<span class="line"><span>   一路找到底还不能 —— 整页刷新</span></span></code></pre></div><p>第 4 步里“能不能热替换”是由<strong>模块自己声明的</strong>。<code>.vue</code> 文件由插件处理， 组件相关的部分默认支持热替换；纯 JavaScript 文件需要手动声明（一般不用管）。</p><h3 id="热更新失效的常见现象" tabindex="-1">热更新失效的常见现象 <a class="header-anchor" href="#热更新失效的常见现象" aria-label="Permalink to &quot;热更新失效的常见现象&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎么处理</th></tr></thead><tbody><tr><td>改代码后页面完全不动</td><td>开发服务器断了，或 WebSocket 被代理拦了</td><td>看终端有没有报错，刷新页面看是否恢复</td></tr><tr><td>每次都整页刷新，状态总丢</td><td>改的文件不支持热替换（比如路由配置文件）</td><td>属于正常行为，改路由结构本来就需要重新初始化</td></tr><tr><td>改了样式没反应</td><td>样式写在了 <code>index.html</code> 的内联 <code>&lt;style&gt;</code> 里</td><td>把样式挪进 <code>src/assets/</code> 或组件内</td></tr><tr><td>改了依赖没反应</td><td>依赖被预构建缓存了</td><td>删 <code>node_modules/.vite</code> 重启</td></tr><tr><td>页面白屏，终端一堆报错</td><td>你写的代码本身有语法错误</td><td>先修语法错误，HMR 会恢复</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一个判断技巧</p><p><strong>页面自动刷新了 vs 页面没反应</strong>，这两种情况指向完全不同的原因。</p><p>自动刷新说明“变了但没法局部替换”，通常是正常的；没反应说明“根本没收到变化通知”， 要查连接。分清楚这两类，排查能省一半时间。</p></div><h2 id="生产态为什么必须用-rollup-打包" tabindex="-1">生产态为什么必须用 Rollup 打包 <a class="header-anchor" href="#生产态为什么必须用-rollup-打包" aria-label="Permalink to &quot;生产态为什么必须用 Rollup 打包&quot;">​</a></h2><p>开发态不打包，代价是浏览器要发几十上百个请求。这在本地无所谓（服务器就在本机）， 但到了线上就不可接受：</p><table tabindex="0"><thead><tr><th>因素</th><th>开发态（不打包）</th><th>生产态（打包）</th></tr></thead><tbody><tr><td>请求数量</td><td>每个模块一个请求</td><td>合并成几个文件</td></tr><tr><td>网络延迟</td><td>本机，几乎为 0</td><td>每个请求都有真实往返延迟</td></tr><tr><td>代码体积</td><td>保留注释、空格、完整变量名</td><td>压缩混淆，删掉调试代码</td></tr><tr><td>兼容性</td><td>假定现代浏览器</td><td>可以按目标浏览器降级语法</td></tr><tr><td>缓存</td><td>无所谓</td><td>文件名带哈希，可长期缓存</td></tr></tbody></table><p>所以 <code>pnpm build</code> 走的是另一条路：用 Rollup 把所有模块分析一遍， 从入口开始顺着 <code>import</code> 关系收集，打成一个依赖图，然后输出到 <code>dist/</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出类似</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v8.3.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> building</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> transformed.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dist/index.html</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                   0.46</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kB</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> │</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gzip:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   0.30</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dist/assets/index-DiwygxGE.css</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   12.34</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kB</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> │</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gzip:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   3.21</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dist/assets/index-B7xK2pQm.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   186.72</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kB</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> │</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gzip:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  62.45</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> built</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3.42s</span></span></code></pre></div><p>这一页输出的每一行都值得读：文件名、原始体积、gzip 之后的体积。 <strong>第 11 周做综合项目时，这份输出就是“产物构成分析”的原始数据。</strong></p><h2 id="和-webpack-比-差在哪" tabindex="-1">和 Webpack 比，差在哪 <a class="header-anchor" href="#和-webpack-比-差在哪" aria-label="Permalink to &quot;和 Webpack 比，差在哪&quot;">​</a></h2><p>Webpack 是上一代的主流选择，现在很多公司仍在用。对比不是为了分好坏， 而是让你知道各自的取向。</p><table tabindex="0"><thead><tr><th>对比项</th><th>Vite</th><th>Webpack</th></tr></thead><tbody><tr><td>配置文件量</td><td>少，常见配置二三十行</td><td>多，几十到几百行常见</td></tr><tr><td>开发服务器启动</td><td>秒级，与项目规模基本无关</td><td>十秒到几分钟，与规模强相关</td></tr><tr><td>底层实现</td><td>开发态用原生 ESM，生产态用 Rollup</td><td>全程自己做打包</td></tr><tr><td>生态</td><td>较新，常用插件都有</td><td><strong>最成熟</strong>，几乎没有找不到的插件</td></tr><tr><td>老项目兼容</td><td>需要一些适配</td><td>天然适合</td></tr><tr><td>学习曲线</td><td>平缓，配置直观</td><td>陡峭，概念多（loader、plugin、chunk 等）</td></tr></tbody></table><p>Webpack 慢的根本原因在于<strong>它必须先打包再启动</strong>：项目越大，要处理的模块越多， 启动就越慢。Vite 把这个顺序反了过来：<strong>先启动，用到什么再编译什么。</strong></p><div class="tip custom-block"><p class="custom-block-title">学哪一个是“够用”的</p><p>本课程用 Vite。但要知道 Webpack 的存在，因为两类场景会碰到它：</p><ol><li>接手老项目 —— 很多 2020 年前后的项目还是 Webpack，你得能看懂配置。</li><li>特殊需求 —— 少数场景 Vite 的生态还不够，需要退回 Webpack。</li></ol><p><strong>理解了“转换 / 解析 / 打包”这三件事，换工具只是换配置写法。</strong></p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>构建工具的存在理由是：浏览器不认识 <code>.vue</code>、<code>.scss</code>、裸模块名和路径别名。</li><li>构建工具做三件事：转换格式、解析模块路径、打包输出。</li><li>Vite 的开发态不打包，用浏览器原生 ES Module 按需编译；生产态用 Rollup 打包。</li><li>冷启动快的原因是依赖预构建（esbuild，结果缓存在 <code>node_modules/.vite/deps</code>）+ 源码按需编译。</li><li>HMR 只重新加载改动的模块，保住页面状态；失效时先分清“自动刷新”还是“没反应”。</li><li>生产态必须打包，因为请求数量、体积、缓存、兼容性四方面都要求这么做。</li><li>与 Webpack 的差别主要在启动速度与生态成熟度，核心概念是相通的。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><details class="details custom-block"><summary>坑 1：改了 vite.config.js 却不生效</summary><p><strong>现象</strong>：明明改了配置，行为却和改之前一样。</p><p><strong>原因</strong>：配置文件只在启动时读一次。别名、插件这类改动不会热更新。</p><p><strong>处理</strong>：<code>Ctrl + C</code> 停掉开发服务器，重新 <code>pnpm dev</code>。</p><p><strong>判断方法</strong>：改 <code>server.port</code> 这种配置，如果端口没变，就是没重启。</p></details><details class="details custom-block"><summary>坑 2：删了 node_modules 之后启动特别慢</summary><p><strong>现象</strong>：重装依赖后第一次 <code>pnpm dev</code> 卡了好几秒。</p><p><strong>原因</strong>：<code>node_modules/.vite/deps</code> 是跟着 <code>node_modules</code> 一起被删掉的， 所以要做一次完整的依赖预构建。</p><p><strong>处理</strong>：这是正常现象，等它跑完就好。<strong>不要以为“Vite 变慢了”。</strong> 第二次启动就恢复正常水平了。</p></details><details class="details custom-block"><summary>坑 3：路径大小写不一致，本地能跑线上报错</summary><p><strong>现象</strong>：本地 <code>pnpm dev</code> 正常，<code>pnpm build</code> 后在服务器上某个组件加载失败。</p><p><strong>原因</strong>：macOS 与 Windows 的文件系统默认<strong>不区分大小写</strong>， <code>import ActivityList from &#39;./activityList.vue&#39;</code> 能找到 <code>ActivityList.vue</code>。 Linux 服务器区分大小写，就找不到了。</p><p><strong>处理</strong>：让 import 的路径和真实文件名<strong>完全一致</strong>。排查时用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出真实文件名，逐个核对 import 写法</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/views</span></span></code></pre></div><p><strong>这类问题必须在 <code>pnpm preview</code> 阶段发现</strong>，不要等部署之后。</p></details><details class="details custom-block"><summary>坑 4：在 dev 里用 process.env 读环境变量</summary><p><strong>现象</strong>：<code>console.log(process.env.VITE_API_BASE)</code> 输出 <code>undefined</code>。</p><p><strong>原因</strong>：Vite 的客户端代码里没有 <code>process</code> 这个对象（那是 Node 环境才有的）， 环境变量要通过 <code>import.meta.env</code> 读。</p><p><strong>处理</strong>：改成 <code>import.meta.env.VITE_API_BASE</code>。详见 <a href="/frontend-engineering-course/unit02/05-env-config.html">2.5 环境变量与常用配置</a>。</p><p><strong>特殊情况</strong>：<code>vite.config.js</code> 是跑在 Node 里的，那里可以用 <code>process.env</code>， 但拿不到 <code>.env</code> 里定义的值 —— 除非用 <code>loadEnv()</code> 显式加载。</p></details><details class="details custom-block"><summary>坑 5：以为 dist 可以直接双击打开</summary><p><strong>现象</strong>：<code>pnpm build</code> 之后直接双击 <code>dist/index.html</code>，页面一片空白。</p><p><strong>原因</strong>：产物里引用的资源路径是 <code>/assets/xxx.js</code>，绝对路径以根目录为起点。 用 <code>file://</code> 打开时根目录变成了本地磁盘根，找不到文件。</p><p><strong>处理</strong>：用 <code>pnpm preview</code> 启动一个本地服务器访问。如果确实需要能双击打开的产物， 在 <code>vite.config.js</code> 里把 <code>base</code> 设成 <code>&#39;./&#39;</code>（相对路径）—— 但这是特殊情况， 正常项目保持默认。</p><p><strong>记住：<code>dist</code> 不是给人双击的，是给服务器托管的。</strong></p></details><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><details class="details custom-block"><summary>练习 1：对比 dev 与 preview 的网络请求</summary><p>分别在 <code>pnpm dev</code> 和 <code>pnpm preview</code> 打开的页面上，用浏览器开发者工具的 Network 面板看请求数量。</p><p>回答：</p><ol><li>两种模式下，页面加载发出的 JS 请求大概各有多少个？</li><li>生产态的文件名有什么特征？开发态的又是什么样？</li><li>为什么生产态的请求数少这么多？</li></ol><p><strong>参考思路</strong>：开发态你会看到几十上百个请求，路径直接对应 <code>src/</code> 下的文件； 生产态只有几个，文件名带一串哈希。原因就是这一节讲的“开发态不打包，生产态打包”。</p><p><strong>顺手做一件事</strong>：把两个模式下的总体积对比一下，记在笔记里。 第 12 周做构建优化时会用到这个基线数字。</p></details><details class="details custom-block"><summary>练习 2：观察依赖预构建的缓存</summary><p>步骤：</p><ol><li>删掉 <code>node_modules/.vite</code>，记录 <code>pnpm dev</code> 从启动到 ready 用了多久。</li><li>停掉，再启动一次，记录时间。</li><li>打开 <code>node_modules/.vite/deps</code>，看看里面有哪些文件。</li></ol><p>回答：为什么第二次更快？缓存目录里为什么只有 <code>vue.js</code>、<code>element-plus.js</code> 这种 合并后的文件，而不是几百个小文件？</p><p><strong>验收点</strong>：能说出“依赖预构建把多个模块合并成一个文件，结果缓存在磁盘上”这一句。</p></details><details class="details custom-block"><summary>练习 3：复现一次热更新失效</summary><p>任务：制造一次“改了代码但页面没反应”，然后定位原因。</p><p>思路（选一种）：</p><ul><li>在 <code>index.html</code> 里加一段内联 <code>&lt;style&gt;</code>，改它，看样式是否跟着变。</li><li>修改 <code>vite.config.js</code> 的 <code>server.port</code>，看端口有没有变。</li><li>在浏览器里手动断开网络一小会儿，改代码，看是否有更新。</li></ul><p><strong>验收点</strong>：要能分清三种情况 —— <strong>整页刷新（正常，模块不支持热替换）</strong>、 <strong>完全没反应（异常，连接或配置问题）</strong>、<strong>报错后白屏（你自己的代码有语法错误）</strong>。 写清楚你遇到的是哪一种，依据是什么。</p></details><details class="details custom-block"><summary>练习 4：给同学讲清“为什么需要构建工具”</summary><p>不看这一节，用三句话解释：</p><ol><li>为什么浏览器不能直接跑 <code>.vue</code> 文件？</li><li>为什么开发时可以不打包，生产时必须打包？</li><li>为什么 Vite 启动比 Webpack 快？</li></ol><p><strong>参考思路</strong>：三句话各自的落点应该是 —— <strong>格式不认识</strong>、<strong>请求数与体积的代价不同</strong>、 <strong>先启动后编译 vs 先编译后启动</strong>。</p><p><strong>检验方法</strong>：找一个没上这门课的同学，讲一遍，看他能不能复述出大意。 讲不清的地方，就是你没真正理解的地方。</p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit02/03-package-json.html">2.3 package.json 逐字段精讲</a> · 下一节：<a href="/frontend-engineering-course/unit02/05-env-config.html">2.5 环境变量与常用配置</a></p>`,67)])])}const g=s(d,[["render",n]]);export{k as __pageData,g as default};
